import{z as s,x as o,o as e,c as d,q as n,j as r,D as E,d as B,s as i,S as l,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"统计学习与市场收束","description":"","frontmatter":{"title":"统计学习与市场收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/slm-map.md","filePath":"quant/slm-map.md","lastUpdated":1791413859000}'),p={name:"quant/slm-map.md"};function m(u,a,f,D,h,C){const t=o("Mermaid");return e(),d("div",null,[a[2]||(a[2]=n('<h1 id="统计学习与市场收束" tabindex="-1">统计学习与市场收束 <a class="header-anchor" href="#统计学习与市场收束" aria-label="Permalink to &quot;统计学习与市场收束&quot;">​</a></h1><div class="epigraph"><p>低信噪比的世界里，稀缺的不是模型，是数字的含义；这门课从头到尾只做了一件事——让每个数字自称的含义成立。</p><footer>—— 据 Gu, Kelly and Xiu, *Review of Financial Studies*, 2020；López de Prado, *Advances in Financial Machine Learning*, Wiley, 2018 的口径整理</footer></div><p><a href="/quant/slm-uncertainty">上一课</a>把点预测补成被检验的预测分布，纪律单元四课过完。本课程到此收束：本课把方法轴与纪律轴合成一张地图，标出各课的接缝、与其他课程的分工，以及带得走的那一条流程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>八课下来每课都守一段边界，真正上手时问题从来是整链：数据、特征、模型、协议、评估、监测、不确定性、仓位。失败的方式恰恰是「只取一段」：拿第 4 课的网络、丢第 6 课的协议；拿第 2 课的 \\(\\lambda\\)、丢第 5 课的台账；拿第 3 课的交互、用 gain 排序立项。每一段单独都对，连起来错——因为链的强度由最松的一格决定，而最松的一格几乎总是在纪律侧。</p><p><span class="marginnote">直觉类比：整条流水线像木桶——能装多少水由最短的板决定，而量化里最短的板几乎总在纪律侧。网络再精巧，测试集只要被「看过一次」，报告的数字就整体作废。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>一条主线按读序回链。特征按滞后与截面 rank 统一（<a href="/quant/cs-rank-features">特征：滞后、截面 rank</a>）；模型按容量递增立基线——正则化线性先行（<a href="/quant/slm-regularization-market-data">正则化与市场数据</a>），树与提升次之（<a href="/quant/slm-trees-boosting">树模型与梯度提升</a>），浅网络最后（<a href="/quant/slm-nn-cross-section">神经网络的截面应用</a>），每一档必须在协议内打败上一档才升级；协议把全部选择关进时间块（<a href="/quant/slm-oos-protocol">样本外协议</a>、<a href="/quant/nested-cv">嵌套交叉验证</a>）；评估报 \\(N\\) 台账与折价（<a href="/quant/backtest-overfitting">过拟合次数与试错</a>、<a href="/quant/pbo">Probability of Backtest Overfitting</a>、<a href="/quant/deflated-sharpe">Deflated Sharpe</a>）；重要性以簇为报告单位（<a href="/quant/slm-feature-importance-pitfalls">特征重要性的陷阱</a>）；预测带分布与校准（<a href="/quant/slm-uncertainty">不确定性量化</a>）；上线后由监测接管（<a href="/quant/live-drift-monitor">实盘漂移监测</a>）。数据流水线与运维的对应账在金融 ML 工程组（<a href="/quant/fml-map">失败模式与收束</a>），另类数据的入口账在另类数据工程组（<a href="/quant/alt-case-map">案例与收束</a>）。</p>',8)),(e(),r(l,null,{default:E(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E7%89%B9%E5%BE%81%EF%BC%9A%E6%BB%9E%E5%90%8E%E4%B8%8E%E6%88%AA%E9%9D%A2%20rank%22%5D%20--%3E%20B%5B%22%E5%9F%BA%E7%BA%BF%EF%BC%9A%E6%AD%A3%E5%88%99%E5%8C%96%E7%BA%BF%E6%80%A7%22%5D%0A%20%20B%20--%3E%20T%5B%22%E6%A0%91%E4%B8%8E%E6%8F%90%E5%8D%87%EF%BC%9A%E4%BA%A4%E4%BA%92%22%5D%0A%20%20T%20--%3E%20N%5B%22%E6%B5%85%E7%BD%91%E7%BB%9C%EF%BC%9A%E8%BF%9E%E7%BB%AD%E5%BD%A2%E6%80%81%22%5D%0A%20%20N%20--%3E%20P%5B%22%E5%8D%8F%E8%AE%AE%EF%BC%9A%E6%97%B6%E9%97%B4%E5%9D%97%E4%B8%8E%E4%B8%80%E6%AC%A1%E6%80%A7%E6%B5%8B%E8%AF%95%22%5D%0A%20%20P%20--%3E%20E%5B%22%E8%AF%84%E4%BC%B0%EF%BC%9AN%20%E5%8F%B0%E8%B4%A6%E4%B8%8E%E6%8A%98%E4%BB%B7%22%5D%0A%20%20E%20--%3E%20I%5B%22%E9%87%8D%E8%A6%81%E6%80%A7%EF%BC%9A%E7%B0%87%E7%BA%A7%E4%B8%8E%E5%A2%9E%E9%87%8F%E6%A3%80%E9%AA%8C%22%5D%0A%20%20I%20--%3E%20U%5B%22%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%A7%EF%BC%9A%E5%8C%BA%E9%97%B4%E4%B8%8E%E6%A0%A1%E5%87%86%22%5D%0A%20%20U%20--%3E%20M%5B%22%E4%B8%8A%E7%BA%BF%EF%BC%9A%E5%BD%B1%E5%AD%90%E7%9B%98%E4%B8%8E%E6%BC%82%E7%A7%BB%E7%9B%91%E6%B5%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"统摄全课程的量是信噪比。它决定容量的上限——噪声方差压倒一切，所以基线从最简模型起步；它决定样本外 \\(R^2\\) 的量级——千分位，所以评估必须用排序口径与组合口径；它决定区间的宽度——噪声底主导，所以不确定性量化从测噪声开始；它也决定重要性的分辨率——共线加低信噪比，所以归因只能到簇。协议之所以高于模型，是因为在这个信噪比下，「数字的含义」比「数字的大小」更稀缺：一个含义成立的千分位，胜过一万个含义不明的样本内拟合。",-1)),(e(),r(l,null,{default:E(()=>[i(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20SNR%5B%22%E4%BD%8E%E4%BF%A1%E5%99%AA%E6%AF%94%22%5D%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E4%B8%8A%E9%99%90%E4%BD%8E%EF%BC%9A%E5%9F%BA%E7%BA%BF%E4%BB%8E%E6%9C%80%E7%AE%80%E6%A8%A1%E5%9E%8B%E8%B5%B7%E6%AD%A5%22%5D%0A%20%20SNR%20--%3E%20R2%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%20R%C2%B2%20%E5%9C%A8%E5%8D%83%E5%88%86%E4%BD%8D%EF%BC%9A%E7%94%A8%E6%8E%92%E5%BA%8F%E4%B8%8E%E7%BB%84%E5%90%88%E5%8F%A3%E5%BE%84%22%5D%0A%20%20SNR%20--%3E%20CI%5B%22%E5%99%AA%E5%A3%B0%E5%BA%95%E4%B8%BB%E5%AF%BC%E5%8C%BA%E9%97%B4%EF%BC%9A%E5%85%88%E6%B5%8B%E5%99%AA%E5%A3%B0%E5%86%8D%E8%B0%88%E9%A2%84%E6%B5%8B%22%5D%0A%20%20SNR%20--%3E%20ATTR%5B%22%E5%85%B1%E7%BA%BF%E5%8A%A0%E4%BD%8E%E4%BF%A1%E5%99%AA%E6%AF%94%EF%BC%9A%E5%BD%92%E5%9B%A0%E5%8F%AA%E8%83%BD%E5%88%B0%E7%B0%87%22%5D%0A%20%20CAP%20--%3E%20CONC%5B%22%E5%90%AB%E4%B9%89%E6%88%90%E7%AB%8B%E7%9A%84%E5%8D%83%E5%88%86%E4%BD%8D%E8%83%9C%E8%BF%87%E5%90%AB%E4%B9%89%E4%B8%8D%E6%98%8E%E7%9A%84%E6%8B%9F%E5%90%88%22%5D%0A%20%20R2%20--%3E%20CONC%0A%20%20CI%20--%3E%20CONC%0A%20%20ATTR%20--%3E%20CONC%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">数字实例：个股月收益的截面标准差以百分之几计，可预测成分若只占千分之一，样本外 \\(R^2\\) 就是 0.001 量级——换算成多空组合的年化增量可以很可观，但按「回归拟合优度」的直觉读，它小得像零。评估要用排序与组合口径，原因在此。</span></p><p><span class="marginnote">收束的口径：Gu-Kelly-Xiu（2020）贡献了「统一协议下的模型竞赛」——方法轴按它的模型谱系展开；López de Prado（2018）贡献了「协议先于模型」的工程化——纪律轴按它的审计要求展开。两份文献的分工，就是本课程两根轴的分工。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不覆盖的部分要指名：因果与结构解释在经济学栏；高频统计的估计量谱系与本栏高频统计课程相接；定价理论的检验与因子溢价的经济学在资产定价课程；数据存储、点时库与执行工程归金融 ML 工程与数据工程各课。方法会过时，纪律不会：模型族可以整格替换——把网络换成任何下一代学习器——七段流程里除了模型那一格，其余格子的义务一条都不变。读到这里，方法轴与纪律轴应当被当成一台机器的两个仓：少装任何一个，另一个都会空转。</p><p><span class="marginnote">常见误区：初学者容易把这门课当成「模型清单」，学会网络就跳过协议。实际上模型格整格可换——下一代学习器来了直接替换——其余格子的义务一条不变：时间块、\\(N\\) 台账、簇级归因、区间校准，换成什么模型都得做。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>整链九格：特征、基线、树、网络、协议、评估、重要性、不确定性、监测；链强由最松一格决定。</li><li>信噪比统摄全课：定容量上限、定 \\(R^2\\) 量级、定区间宽度、定归因分辨率。</li><li>协议高于模型：含义成立的千分位胜过含义不明的样本内拟合。</li><li>模型格可替换，纪律格的义务不随模型变；相邻课程的分工已逐格指名。</li><li>出处：Gu, Kelly and Xiu, <em>Empirical Asset Pricing via Machine Learning</em>, <em>RFS</em>, 2020；López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018。</li></ul>',7))])}const q=s(p,[["render",m]]);export{F as __pageData,q as default};
